from .model_exceptions import ManagedObjectDataIncorrect, EnumerationDoesNotHaveValue
from .parameter import Parameter, ComplexParameter


class ManagedObject(object):

    def __init__(self, class_name, domain, product, package_name, package_id=None, name=None):
        """
        NiddModel creation based on provided parameters.
        Converts list of parameter data into keyword accessible parameters structure - based on paramAbbr value.

        :param name: Name of the nidd model
        :param domain: Nidd domain name
        :param product: Nidd product name
        :param package_name: Nidd package version name
        """
        if name is None:
            name = class_name

        self.class_name = class_name
        self.name = name
        self.domain = domain
        self.product = product
        self.package_name = package_name
        self.parameters = {}
        self.package_id = package_id
        self.__related_child_managed_object_list = []

    def __create_parameter_from_xml(self, data):
        """
        Creates NiddParameter or NiddComplexParameter objects based on data from XML.
        :param data: XML Element data of NIDD parameter object
        :return: NiddParameter or NiddComplexParameter
        """
        attributes = {
            "id": data.get("id"),
            "param_abbr": data.get("name"),
            "moc_name": self.name,
            "package_name": self.package_name,
            "package_id": data.get("releaseId"),
            "param_name": data.get("fullName"),
            "status_name": data.get("status"),
            "class_name": self.class_name
        }
        complex_type_data = data.find("complexType")
        description_data = data.find("description")
        modification = data.find("modification")
        related_functions_data = data.find("relatedFunctions")
        related_features_data = data.find("features")
        creation_data = data.find('creation')

        if complex_type_data is not None:
            nidd_parameter = ComplexParameter(
                data_type_name="Structure",
                description=self.__get_desc_data(description_data, tag="para"),
                related_functions=self.__get_related_data(related_functions_data, tag="function"),
                related_features=self.__get_related_data(related_features_data, tag="feature"),
                modification=modification.get("type").lower(),
                value_range=self.__get_value_range_data(complex_type_data),
                creation=creation_data.get("priority"),
                **attributes
            )
            for sub_parameter_data in complex_type_data.iterchildren(tag="p"):
                nidd_sub_parameter = self.__create_parameter_from_xml(data=sub_parameter_data)
                nidd_parameter.add_parameter(parameter=nidd_sub_parameter)
        else:
            simple_type_data = data.find("simpleType")

            special = simple_type_data.find('special')
            attributes["special"] = special.get('text') if special is not None else None

            editing_data = simple_type_data.find("editing")

            if editing_data is not None:
                type_value_data = editing_data
            else:
                type_value_data = simple_type_data

            default_value = self.__get_default_value(type_value_data)
            if default_value is not None:
                attributes["default_value"] = default_value

            enum_data_values = self.__get_enum_data_values(type_value_data)
            if enum_data_values is not None:
                attributes["enum_data_values"] = enum_data_values

            nidd_parameter = Parameter(
                data_type_name=simple_type_data.get("base"),
                description=self.__get_desc_data(description_data, tag="para"),
                related_functions=self.__get_related_data(related_functions_data, tag="function"),
                related_features=self.__get_related_data(related_features_data, tag="feature"),
                modification=modification.get("type"),
                value_range=self.__get_value_range_data(type_value_data),
                creation=creation_data.get("priority"),
                **attributes
            )
        return nidd_parameter

    def __get_value_range_data(self, type_value_data):
        range_data = type_value_data.find("range")

        if range_data is not None:
            min_length = range_data.get("minIncl")
            max_length = range_data.get("maxIncl")
            values = [min_length, max_length]
            return values
        else:
            min_length = type_value_data.find("minLength")
            max_length = type_value_data.find("maxLength")
            if min_length is not None and max_length is not None:
                values = [min_length.get("value"), max_length.get("value")]
                return values

    def __get_default_value(self, type_value_data):
        default_data = type_value_data.find("default")

        if default_data is not None:
            default_data_value = default_data.get("value")

            return self.__default_value(type_value_data, default_data_value)

    def __default_value(self, type_value_data, default_data_value):
        if type_value_data.find("enumeration") is None:
            return default_data_value
        else:
            return self.__get_enum_value(type_value_data, default_data_value)

    def __get_enum_value(self, type_value_data, expected):
        enumeration_values = type_value_data.iterchildren(tag="enumeration")
        for enum_object in enumeration_values:
            if enum_object.get("value") == expected:
                return enum_object.get("text")
        else:
            error_msg = "Enumeration index {} does not correspond to any value in enum {}"
            return EnumerationDoesNotHaveValue(error_msg.format(expected, enumeration_values))

    def __get_enum_data_values(self, type_value_data):
        xml_data = type_value_data.find("enumeration")

        if xml_data is None:
            return None

        values = [enum_object.get("text") for enum_object in type_value_data.iterchildren(tag="enumeration")]
        return values

    def __get_desc_data(self, type_value_data, tag):
        description_content = [desc_object.text for desc_object in type_value_data.iterchildren(tag=tag)]
        return description_content

    def __get_related_data(self, type_value_data, tag):
        if type_value_data is None:
            return None

        values = [related_functions.get("name") for related_functions in type_value_data.iterchildren(tag=tag)]
        return values

    def update_model_from_xml(self, xml_data):
        """
        Update NiddManagedObject attributes and parameters from advanced Standard XML Report NIDD API loaded in NiddPackage
        :param xml_data: XML Element data of managedObject
        """
        if self.class_name != xml_data.get("class", None):
            raise ManagedObjectDataIncorrect(
                "managedObject xml data does not belong to managed object you are trying to update"
            )

        for child_managed_object in xml_data.iterchildren(tag="childManagedObject"):
            self.__related_child_managed_object_list.append(child_managed_object.get("class"))

        for parameter_data in xml_data.iterchildren(tag="p"):
            nidd_parameter = self.__create_parameter_from_xml(data=parameter_data)
            self.parameters[nidd_parameter.param_abbr] = nidd_parameter
